public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
	// Check if the start and end points are the same
	if (Arrays.equals(start, end)) {
		return "can be travelled";
	}

	// Check if the starting point is not at the edge of the maze
	if (!(start[0] == 0 || start[0] == n - 1 || start[1] == 0 || start[1] == n - 1)) {
		return "cannot be travelled";
	}

	// Check if the ending point is not at the edge of the maze
	if (!(end[0] == 0 || end[0] == n - 1 || end[1] == 0 || end[1] == n - 1)) {
		return "cannot be travelled";
	}

	// Check if the starting point is in the maze
	if (!(start[0] >= 0 && start[0] < n && start[1] >= 0 && start[1] < n)) {
		return "cannot be travelled";
	}

	// Check if the ending point is in the maze
	if (!(end[0] >= 0 && end[0] < n && end[1] >= 0 && end[1] < n)) {
		return "cannot be travelled";
	}

	// Check if there is a path between the start and end points
	boolean[][] visited = new boolean[n][n];
	Arrays.fill(visited[0], false);
	Arrays.fill(visited[n - 1], false);
	Arrays.fill(visited[0][0], true);
	Arrays.fill(visited[0][n - 1], true);
	Arrays.fill(visited[n - 1][0], true);
	Arrays.fill(visited[n - 1][n - 1], true);
	Queue<int[]> queue = new LinkedList<>();
	queue.offer(start);
	while (!queue.isEmpty()) {
		int[] node = queue.poll();
		for (int[] path : paths) {
			int[] nextNode = new int[] {node[0] + path[0], node[1] + path[1]};
			if (nextNode[0] == end[0] && nextNode[1] == end[1]) {
				return "can be travelled";
			}
			if (!visited[nextNode[0]][nextNode[1]]) {
				visited[nextNode[0]][nextNode[1]] = true;
				queue.offer(nextNode);
			}
		}
	}
	return "cannot be travelled";
}

