public static String appx(String word1, String word2) {
    // Initialize variables
    int commonLetters = 0;
    int word1Length = word1.length();
    int word2Length = word2.length();

    // Find the number of common letters
    for (int i = 0; i < word1Length; i++) {
        for (int j = 0; j < word2Length; j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonLetters++;
                break;
            }
        }
    }

    // Calculate the approximate value
    int numerator = commonLetters;
    int denominator = word1Length + word2Length;
    double approxValue = (double) numerator / denominator;

    // Return the reduced fraction as a string
    return "appx(" + word1 + ", " + word2 + ") = " + approxValue;
}

