    // Initialize a graph using the given edges
    Graph graph = new Graph(n, edges);

    // Initialize a queue to store the nodes to visit
    Queue<Node> queue = new LinkedList<>();
    queue.add(new Node(0));

    // Initialize a set to keep track of the visited nodes
    Set<Node> visited = new HashSet<>();

    // Initialize a variable to keep track of the minimum time
    int minTime = 0;

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current node from the queue
        Node current = queue.poll();

        // If the current node has an apple and it has not been visited before, mark it as visited and increment the minimum time
        if (hasApple[current.index] && !visited.contains(current)) {
            visited.add(current);
            minTime++;
        }

        // For each of the current node's children, add them to the queue
        for (int childIndex : graph.children[current.index]) {
            queue.add(new Node(childIndex));
        }
    }

    // Return the minimum time
    return minTime;
}

