public static int findSmallestInteger(int n) {
    if (n < 10) {
        return -1;
    }

    // Find the smallest integer that can be formed by rearranging the digits
    // of the given positive integer n, which is greater than n.
    String numStr = String.valueOf(n);
    char[] numChars = numStr.toCharArray();
    Arrays.sort(numChars);
    StringBuilder smallestIntegerStr = new StringBuilder();
    for (char c : numChars) {
        smallestIntegerStr.append(c);
    }
    int smallestInteger = Integer.parseInt(smallestIntegerStr.toString());

    // If the smallest integer is greater than n, return it. Otherwise,
    // return -1 to indicate that no such integer can be formed.
    return smallestInteger > n ? smallestInteger : -1;
}

